def transform(grid):
    """Stamp the sparse marker shape onto every matching all-zero placement."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {v: sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    marker = min((v for v in counts if v not in (0,)), key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = {(r - r0, c - c0) for r, c in points}
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1

    for dr in range(h - sh + 1):
        for dc in range(w - sw + 1):
            if all(grid[dr + r][dc + c] == 0 for r, c in shape):
                for r, c in shape:
                    out[dr + r][dc + c] = marker
    return out
